def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'
    me = [h[0] for h in history]
    opp = [h[1] for h in history]
    last_me = me[-1]
    last_opp = opp[-1]
    if opp.count('C') == 0 and n >= 4:
        return 'D'
    cd_streak = 0
    for i in range(n - 1, -1, -1):
        if me[i] == 'C' and opp[i] == 'D':
            cd_streak += 1
        else:
            break
    if last_opp == 'C':
        return 'C'
    else:
        if last_me == 'D':
            return 'C'
        else:
            if cd_streak >= 2:
                return 'D'
            else:
                return 'C'
